"""The rule-graph diagrams in docs/img/ are generated by scripts/make_dag.py from `snakemake --rulegraph`.

These tests fail when the workflow changes but the committed diagrams were not regenerated
(run `python scripts/make_dag.py`). Skipped when snakemake is not installed.
"""
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
pytestmark = pytest.mark.skipif(shutil.which("snakemake") is None and not (Path(sys.executable).parent / "snakemake").exists(),
                                reason="snakemake not installed")


def run(*args):
    import os
    env = dict(os.environ)
    env["PATH"] = str(Path(sys.executable).parent) + os.pathsep + env.get("PATH", "")  # find snakemake next to python
    return subprocess.run([sys.executable, "scripts/make_dag.py", *args], cwd=ROOT, capture_output=True, text=True, env=env)


def test_committed_dags_are_current():
    r = run("--check")
    assert r.returncode == 0, r.stderr or r.stdout


def test_full_graph_has_every_branch():
    mmd = (ROOT / "docs" / "img" / "dag_full.mmd").read_text()
    for rule in ("fastp", "star_index", "bigwig_sample", "fgsea", "rnk", "multiqc", "deseq2", "qc_report"):
        assert f"{rule}[{rule}]" in mmd, rule
    assert "all[" not in mmd   # the target rule is dropped


def test_analysis_only_graph_has_no_alignment():
    mmd = (ROOT / "docs" / "img" / "dag_analysis.mmd").read_text()
    assert "star_align" not in mmd and "deseq2" in mmd


def test_readme_and_code_guide_embed_the_current_full_dag():
    body = "".join((ROOT / "docs" / "img" / "dag_full.mmd").read_text().splitlines(keepends=True)[1:])
    for name in ("README.md", "CODE_GUIDE.md"):
        txt = (ROOT / name).read_text()
        assert f"<!-- dag:start -->\n```mermaid\n{body}```\n<!-- dag:end -->" in txt, name
